===== core/ALU.v =====
`timescale 1ns / 1ps

module ALU(
    input[31:0] A, B,
    input[3:0] Control,
    output[31:0] res,
    output zero, overflow
);

    parameter ALU_ADD  = 4'b0001;
    parameter ALU_SUB  = 4'b0010;
    parameter ALU_AND  = 4'b0011;
    parameter ALU_OR   = 4'b0100;
    parameter ALU_XOR  = 4'b0101;
    parameter ALU_SLL  = 4'b0110;
    parameter ALU_SRL  = 4'b0111;
    parameter ALU_SLT  = 4'b1000;
    parameter ALU_SLTU = 4'b1001;
    parameter ALU_SRA  = 4'b1010;
    parameter ALU_Ap4  = 4'b1011;
    parameter ALU_Bout = 4'b1100;

    // TODO: implement — compute the ALU result, zero flag, and overflow flag
    // The ALU must support: ADD, SUB, AND, OR, XOR, SLL, SRL, SLT, SLTU, SRA, A+4, B-passthrough
    // Use the Control input to select which operation to perform.
    // zero should be 1 when res is all zeros.
    // overflow should be set for signed ADD/SUB overflow.
    assign res = 32'b0;
    assign zero = 1'b0;
    assign overflow = 1'b0;

endmodule===== core/CtrlUnit.v =====
`timescale 1ns / 1ps


module CtrlUnit(
    input[31:0] inst,
    input cmp_res,
    output Branch, ALUSrc_A, ALUSrc_B, DatatoReg, RegWrite, mem_w,
        MIO, rs1use, rs2use,
    output [1:0] hazard_optype,
    output [2:0] ImmSel, cmp_ctrl,
    output [3:0] ALUControl,
    output JALR
);

    wire[6:0] funct7 = inst[31:25];
    wire[2:0] funct3 = inst[14:12];
    wire[6:0] opcode = inst[6:0];

    wire Rop = opcode == 7'b0110011;
    wire Iop = opcode == 7'b0010011;
    wire Bop = opcode == 7'b1100011;
    wire Lop = opcode == 7'b0000011;
    wire Sop = opcode == 7'b0100011;

    wire funct7_0  = funct7 == 7'h0;
    wire funct7_32 = funct7 == 7'h20;

    wire funct3_0 = funct3 == 3'h0;
    wire funct3_1 = funct3 == 3'h1;
    wire funct3_2 = funct3 == 3'h2;
    wire funct3_3 = funct3 == 3'h3;
    wire funct3_4 = funct3 == 3'h4;
    wire funct3_5 = funct3 == 3'h5;
    wire funct3_6 = funct3 == 3'h6;
    wire funct3_7 = funct3 == 3'h7;

    wire ADD  = Rop & funct3_0 & funct7_0;
    wire SUB  = Rop & funct3_0 & funct7_32;
    wire SLL  = Rop & funct3_1 & funct7_0;
    wire SLT  = Rop & funct3_2 & funct7_0;
    wire SLTU = Rop & funct3_3 & funct7_0;
    wire XOR  = Rop & funct3_4 & funct7_0;
    wire SRL  = Rop & funct3_5 & funct7_0;
    wire SRA  = Rop & funct3_5 & funct7_32;
    wire OR   = Rop & funct3_6 & funct7_0;
    wire AND  = Rop & funct3_7 & funct7_0;

    wire ADDI  = Iop & funct3_0;	
    wire SLTI  = Iop & funct3_2;
    wire SLTIU = Iop & funct3_3;
    wire XORI  = Iop & funct3_4;
    wire ORI   = Iop & funct3_6;
    wire ANDI  = Iop & funct3_7;
    wire SLLI  = Iop & funct3_1 & funct7_0;
    wire SRLI  = Iop & funct3_5 & funct7_0;
    wire SRAI  = Iop & funct3_5 & funct7_32;

    wire BEQ  = 1'b0; // TODO: implement — decode BEQ from Bop and funct3
    wire BNE  = 1'b0; // TODO: implement
    wire BLT  = 1'b0; // TODO: implement
    wire BGE  = 1'b0; // TODO: implement
    wire BLTU = 1'b0; // TODO: implement
    wire BGEU = 1'b0; // TODO: implement

    wire LB  = 1'b0; // TODO: implement — decode load subtypes from Lop and funct3
    wire LH  = 1'b0; // TODO: implement
    wire LW  = 1'b0; // TODO: implement
    wire LBU = 1'b0; // TODO: implement
    wire LHU = 1'b0; // TODO: implement

    wire SB = 1'b0; // TODO: implement — decode store subtypes from Sop and funct3
    wire SH = 1'b0; // TODO: implement
    wire SW = 1'b0; // TODO: implement

    wire LUI   = 1'b0; // TODO: implement — decode from opcode
    wire AUIPC = 1'b0; // TODO: implement

    wire JAL  = 1'b0; // TODO: implement
    assign JALR = 1'b0; // TODO: implement

    wire R_valid = AND | OR | ADD | XOR | SLL | SRL | SRA | SUB | SLT | SLTU;
    wire I_valid = ANDI | ORI | ADDI | XORI | SLLI | SRLI | SRAI | SLTI | SLTIU;
    wire B_valid = BEQ | BNE | BLT | BGE | BLTU | BGEU;
    wire L_valid = LW | LH | LB | LHU | LBU;
    wire S_valid = SW | SH | SB;


    assign Branch = 1'b0; // TODO: implement — set when branch taken or unconditional jump

    parameter Imm_type_I = 3'b001;
    parameter Imm_type_B = 3'b010;
    parameter Imm_type_J = 3'b011;
    parameter Imm_type_S = 3'b100;
    parameter Imm_type_U = 3'b101;
    assign ImmSel = {3{I_valid | JALR | L_valid}} & Imm_type_I |
                    {3{B_valid}}                  & Imm_type_B |
                    {3{JAL}}                      & Imm_type_J |
                    {3{S_valid}}                  & Imm_type_S |
                    {3{LUI | AUIPC}}              & Imm_type_U ;


    assign cmp_ctrl = 3'b000; // TODO: implement — select comparison type for cmp_32 based on branch subtype

    assign ALUSrc_A = 1'b0; // TODO: implement — 1 for AUIPC/JAL/JALR (uses PC), 0 for others

    assign ALUSrc_B = 1'b0; // TODO: implement — 1 for immediate-type instructions, 0 for R-type

    parameter ALU_ADD  = 4'b0001;
    parameter ALU_SUB  = 4'b0010;
    parameter ALU_AND  = 4'b0011;
    parameter ALU_OR   = 4'b0100;
    parameter ALU_XOR  = 4'b0101;
    parameter ALU_SLL  = 4'b0110;
    parameter ALU_SRL  = 4'b0111;
    parameter ALU_SLT  = 4'b1000;
    parameter ALU_SLTU = 4'b1001;
    parameter ALU_SRA  = 4'b1010;
    parameter ALU_Ap4  = 4'b1011;
    parameter ALU_Bout = 4'b1100;
    assign ALUControl = {4{ADD | ADDI | L_valid | S_valid | AUIPC}} & ALU_ADD  |
                        {4{SUB}}                                    & ALU_SUB  |
                        {4{AND | ANDI}}                             & ALU_AND  |
                        {4{OR | ORI}}                               & ALU_OR   |
                        {4{XOR | XORI}}                             & ALU_XOR  |
                        {4{SLL | SLLI}}                             & ALU_SLL  |
                        {4{SRL | SRLI}}                             & ALU_SRL  |
                        {4{SLT | SLTI}}                             & ALU_SLT  |
                        {4{SLTU | SLTIU}}                           & ALU_SLTU |
                        {4{SRA | SRAI}}                             & ALU_SRA  |
                        {4{JAL | JALR}}                             & ALU_Ap4  |
                        {4{LUI}}                                    & ALU_Bout ;

    assign DatatoReg = L_valid;

    assign RegWrite = R_valid | I_valid | JAL | JALR | L_valid | LUI | AUIPC;

    assign mem_w = S_valid;

    assign MIO = L_valid | S_valid;

    assign rs1use = 1'b0; // TODO: implement — 1 for instructions that read rs1 register

    assign rs2use = 1'b0; // TODO: implement — 1 for instructions that read rs2 register

    assign hazard_optype = 2'b00; // TODO: implement — 2'b10 for loads, 2'b01 for other writes, 2'b00 for no write

endmodule===== core/HazardDetectionUnit.v =====
`timescale 1ps/1ps

module HazardDetectionUnit(
    input clk,
    input Branch_ID, rs1use_ID, rs2use_ID,
    input[1:0] hazard_optype_ID,
    input[4:0] rd_EXE, rd_MEM, rs1_ID, rs2_ID, rs2_EXE,
    output PC_EN_IF, reg_FD_EN, reg_FD_stall, reg_FD_flush,
        reg_DE_EN, reg_DE_flush, reg_EM_EN, reg_EM_flush, reg_MW_EN,
    output forward_ctrl_ls,
    output[1:0] forward_ctrl_A, forward_ctrl_B
);
    // TODO: implement hazard detection and forwarding control
    // Hints:
    // - Stall (PC_EN_IF=0, reg_FD stall, reg_DE flush) when the instruction in EX
    //   writes a register that the ID instruction reads.
    // - Branch (reg_FD_flush=1) when Branch_ID is asserted; do NOT flush reg_DE.
    // - forward_ctrl_A/B: select 2'b01 to forward from MEM stage when rd_MEM
    //   matches the ID instruction's source register.
    // - The register file has write-through for WB, so no explicit WB forwarding needed.
    // - forward_ctrl_ls: forward MEM result to store data when rd_MEM == rs2_EXE.
    // - Use hazard_optype_ID registered one cycle (to get EX stage type) for stall guard.

    assign PC_EN_IF     = 1'b1; // TODO: implement
    assign reg_FD_EN    = 1'b1; // TODO: implement
    assign reg_FD_stall = 1'b0; // TODO: implement
    assign reg_FD_flush = 1'b0; // TODO: implement
    assign reg_DE_EN    = 1'b1; // TODO: implement
    assign reg_DE_flush = 1'b0; // TODO: implement
    assign reg_EM_EN    = 1'b1;
    assign reg_EM_flush = 1'b0;
    assign reg_MW_EN    = 1'b1;
    assign forward_ctrl_ls = 1'b0; // TODO: implement
    assign forward_ctrl_A  = 2'b00; // TODO: implement
    assign forward_ctrl_B  = 2'b00; // TODO: implement

endmodule
