module   REG_EX_MEM(input clk,                                      //EX/MEM Latch
                    input rst,
                    input EN,                                       //流水寄存器使能?
                    input flush,                                    //异常时清除异常指令并等待中断处理(保留)?
                    input [31:0] IR_EX,                             //当前执行指令(测试)
                    input [31:0] PCurrent_EX,                       //当前执行指令存储器指针
                    input [31:0] ALUO_EX,                           //当前ALU执行输出：有效地址或ALU操作
                    input [31:0] B_EX,                              //ID级读出寄存器B数据：CPU输出数据
                    input [4:0]  rd_EX,                             //传递当前指令写目的寄存器地址
                    input DatatoReg_EX,                             //传递当前指令REG写数据通道选择
                    input RegWrite_EX,                              //传递当前指令寄存器写信号?
                    input WR_EX,                                    //传递当前指令存储器读写信号
                    input[2:0] u_b_h_w_EX,
                    input MIO_EX,

                    output reg[31:0] PCurrent_MEM,                  //锁存传递当前指令地址?
                    output reg[31:0] IR_MEM,                        //锁存传递当前指令(测试)
                    output reg[31:0] ALUO_MEM,                      //锁存ALU操作结果：有效地址或ALU操作
                    output reg[31:0] Datao_MEM,                     //锁存传递当前指令输出MIO数据
                    output reg[4:0]  rd_MEM,                        //锁存传递当前指令写目的寄存器地址
                    output reg       DatatoReg_MEM,                 //锁存传递当前指令REG写数据通道选择
                    output reg       RegWrite_MEM,                  //锁存传递当前指令寄存器写信号?
                    output reg       WR_MEM,                        //锁存传递当前指令存储器读写信号
                    output reg[2:0]  u_b_h_w_MEM,
                    output reg       MIO_MEM
                );

    // TODO: implement — EX/MEM pipeline register
    // On reset: clear IR_MEM, PCurrent_MEM, rd_MEM, RegWrite_MEM, WR_MEM, MIO_MEM to 0.
    // When EN is asserted: latch all input signals to their corresponding output registers
