                    input flush,                                       //数据竞争清除并等待：DStall
                    input [31:0] IR_ID,                                //当前译码指令(测试)
                    input [31:0] PCurrent_ID,                          //当前译码指令存储器指令
                    input [4:0] rs1_addr,                              //当前指令读出寄存器A地址
                    input [4:0] rs2_addr,                              //当前指令读出寄存器B地址
